 for(var d=1;d<=days;d++){var n=dayIndexForDate(y,m,d),valid=n>=1&&n<=420,count=valid?dayActivityCount(n):0,done=valid?dayDoneCount(n):0,key=dateKey(y,m,d),sel=state.selectedDate===key,cls='imm-cal-day'+(sel?' selected':'')+(count?' has-items':'')+(count&&done===count?' done':'');html+='<button class="'+cls+'" '+(!valid?'disabled':'')+' onclick="ticImmSelectDate('+y+','+m+','+d+')" title="'+key+'" aria-label="'+key+'"><b>'+d+'</b><small>'+(valid?(count?(done+'/'+count+' feitas'):'Sem aula'):'Fora do plano')+'</small></button>';}
