function localDate(d){d=d||new Date();return dateKey(d.getFullYear(),d.getMonth()+1,d.getDate());}
function todayActivity(){var n=dayIndexForDate(CURRENT_YEAR,CURRENT_DATE.getMonth()+1,CURRENT_DATE.getDate());var a=state.activities.find(function(x){return plannerDayNumber(x)===n;});if(a)return a;return state.activities.filter(function(x){return statusFor(x.id)!=='completed';}).sort(function(a,b){return plannerDayNumber(a)-plannerDayNumber(b);})[0]||state.activities[0]||null;}
function todaySession(){var k=localDate();return (state.daily.sessions||[]).find(function(x){return x.session_date===k;})||null;}
async function loadDailyData(){if(teacherMode()||!state.student){state.daily={sessions:[],vocabulary:[]};return;}var sid=state.student.id;var rs=await Promise.all([sb.from('tic_immersion_sessions').select('*').eq('student_id',sid).order('session_date',{ascending:false}).limit(90),sb.from('tic_immersion_vocabulary').select('*').eq('student_id',sid).order('due_date').limit(250)]);if(!rs[0].error)state.daily.sessions=rs[0].data||[];if(!rs[1].error)state.daily.vocabulary=rs[1].data||[];}
function sessionStreak(){var days={};(state.daily.sessions||[]).filter(function(x){return x.status==='completed';}).forEach(function(x){days[x.session_date]=true;});var d=new Date();if(!days[localDate(d)])d.setDate(d.getDate()-1);var n=0;while(days[localDate(d)]&&n<365){n++;d.setDate(d.getDate()-1);}return n;}
function weekMinutes(){var d=new Date();d.setDate(d.getDate()-6);var k=localDate(d);return (state.daily.sessions||[]).filter(function(x){return x.session_date>=k&&x.status==='completed';}).reduce(function(n,x){return n+(Number(x.duration_minutes)||0);},0);}
